datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Product {
  id         Int         @id @default(autoincrement())
  name       String
  price      Float
  inventory  Int
  orderItems OrderItem[]
}

model Coupon {
  id    Int    @id @default(autoincrement())
  code  String @unique
  type  String // "PERCENTAGE" or "FLAT"
  value Float
}

model Order {
  id         Int         @id @default(autoincrement())
  createdAt  DateTime    @default(now())
  couponCode String?
  discount   Float
  subtotal   Float
  total      Float
  orderItems OrderItem[]
}

model OrderItem {
  id        Int     @id @default(autoincrement())
  orderId   Int
  order     Order   @relation(fields: [orderId], references: [id])
  productId Int
  product   Product @relation(fields: [productId], references: [id])
  quantity  Int
  price     Float
}

export async function devSeed(prisma: any) {
  // Seed Products
  const productCount = await prisma.product.count();
  if (productCount === 0) {
    await prisma.product.createMany({
      data: [
        { name: "Premium Wireless Headphones", price: 100.00, inventory: 10 },
        { name: "Ergonomic Mechanical Keyboard", price: 150.00, inventory: 1 }
      ]
    });
  }

  // Seed Coupons
  const couponCount = await prisma.coupon.count();
  if (couponCount === 0) {
    await prisma.coupon.createMany({
      data: [
        { code: "SAVE20", type: "PERCENTAGE", value: 20.0 },
        { code: "FLAT50", type: "FLAT", value: 50.0 }
      ]
    });
  }
}

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { getProducts } from "./src/queries" with { type: "ref" };
import { applyCoupon, checkout } from "./src/actions" with { type: "ref" };
import { devSeed } from "./src/dbSeeds" with { type: "ref" };

export default app({
  name: "app",
  title: "Wasp E-commerce Checkout",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  db: {
    seeds: [devSeed],
  },
  spec: [
    route("RootRoute", "/", page(MainPage)),
    query(getProducts, {
      entities: ["Product", "Coupon"],
    }),
    action(applyCoupon, {
      entities: ["Coupon"],
    }),
    action(checkout, {
      entities: ["Product", "Coupon", "Order", "OrderItem"],
    }),
  ],
});

import { devSeed } from "./dbSeeds";

export const getProducts = async (args: any, context: any) => {
  const Product = context.entities.Product;

  const productCount = await Product.count();
  if (productCount === 0) {
    const prisma = context.prisma;
    if (prisma) {
      await devSeed(prisma);
    } else {
      // Fallback
      await Product.createMany({
        data: [
          { name: "Premium Wireless Headphones", price: 100.00, inventory: 10 },
          { name: "Ergonomic Mechanical Keyboard", price: 150.00, inventory: 1 }
        ]
      });
      if (context.entities.Coupon) {
        await context.entities.Coupon.createMany({
          data: [
            { code: "SAVE20", type: "PERCENTAGE", value: 20.0 },
            { code: "FLAT50", type: "FLAT", value: 50.0 }
          ]
        });
      }
    }
  }

  return Product.findMany({
    orderBy: { id: "asc" },
  });
};

export const applyCoupon = async (args: { code: string }, context: any) => {
  const Coupon = context.entities.Coupon;
  const coupon = await Coupon.findUnique({
    where: { code: args.code.toUpperCase() }
  });
  if (!coupon) {
    throw new Error("Invalid coupon code");
  }
  return coupon;
};

export const checkout = async (
  args: {
    items: { productId: number; quantity: number }[];
    couponCode?: string;
  },
  context: any
) => {
  const prisma = context.prisma;
  if (!prisma) {
    throw new Error("Prisma client not found in context");
  }

  if (!args.items || args.items.length === 0) {
    throw new Error("Your cart is empty");
  }

  const isPostgres = process.env.DATABASE_URL?.startsWith("postgres") || process.env.DATABASE_URL?.startsWith("postgresql");

  return await prisma.$transaction(async (tx: any) => {
    let subtotal = 0;
    const productMap: Record<number, any> = {};

    for (const item of args.items) {
      if (item.quantity <= 0) {
        throw new Error("Quantity must be greater than 0");
      }

      let product: any = null;
      if (isPostgres) {
        const products = await tx.$queryRawUnsafe(
          `SELECT * FROM "Product" WHERE id = $1 FOR UPDATE`,
          item.productId
        );
        if (Array.isArray(products) && products.length > 0) {
          product = products[0];
        }
      } else {
        product = await tx.product.findUnique({
          where: { id: item.productId }
        });
      }

      if (!product) {
        throw new Error(`Product with ID ${item.productId} not found`);
      }

      if (product.inventory < item.quantity) {
        throw new Error(`Insufficient inventory. Out of stock.`);
      }

      await tx.product.update({
        where: { id: product.id },
        data: {
          inventory: product.inventory - item.quantity
        }
      });

      subtotal += product.price * item.quantity;
      productMap[product.id] = product;
    }

    let discount = 0;
    let coupon: any = null;
    if (args.couponCode) {
      coupon = await tx.coupon.findUnique({
        where: { code: args.couponCode.toUpperCase() }
      });
      if (!coupon) {
        throw new Error("Invalid coupon code");
      }

      if (coupon.type === "PERCENTAGE") {
        discount = subtotal * (coupon.value / 100.0);
      } else if (coupon.type === "FLAT") {
        discount = coupon.value;
      }
    }

    let total = subtotal - discount;
    if (total < 0) {
      total = 0;
    }

    const order = await tx.order.create({
      data: {
        couponCode: args.couponCode || null,
        subtotal,
        discount,
        total,
        orderItems: {
          create: args.items.map((item: any) => {
            const prod = productMap[item.productId];
            return {
              productId: item.productId,
              quantity: item.quantity,
              price: prod.price
            };
          })
        }
      }
    });

    return {
      orderId: order.id,
      subtotal,
      discount,
      total
    };
  });
};

